        title = LocalizedText("""Novena a San Rafael para solteros que buscan esposo o esposa""", """St. Raphael Novena for Singles to Find a Spouse""", """Novena a São Rafael para solteiros encontrarem um cônjuge"""),
        patron = LocalizedText("""Santo patrón de los solteros que buscan cónyuge, los novios y los prometidos, los encuentros felices, los viajeros y los enfermos""", """Patron saint of single people seeking a spouse, courtship and engaged couples, happy meetings, travellers, and the sick""", """Novena a São Rafael para solteiros encontrarem um cônjuge"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Recordatorios diarios + intenciones + oraciones grupales""", """Daily reminders + prayer intentions + group prayers""", """Santo padroeiro de os solteiros que procuram um cônjuge, os namorados e noivos, os encontros felizes, os viajantes e os enfermos"""),
